<body>
    <h1>🤖 Hermes Project Command Center</h1>
    <p>Selamat datang di workstation.upshalter.com/hermes/ - Pusat komando AI Agent Upshalter.</p>

    <div class="grid">
        <div class="card">
            <h2>📡 Agent Status</h2>
            <div id="agents">Loading...</div>
        </div>

        <div class="card">
            <h2>📋 Active Tasks</h2>
            <div id="tasks">Loading...</div>
        </div>

        <div class="card">
            <h2>🔗 Quick Links</h2>
            <ul>
                <li><a href="/hermes/workspace/">→ Workspace (Agent Interface)</a></li>
                <li><a href="/hermes/kanban/">→ Kanban Board</a></li>
                <li><a href="/hermes/api/agents">→ API: Agents</a></li>
                <li><a href="/hermes/api/knowledge">→ API: Knowledge Pool</a></li>
            </ul>
        </div>
    </div>

    <script>
        const API_BASE = '/hermes/api';

        async function fetchData() {
            try {
                const agentsResp = await fetch(`${API_BASE}/agents`);
                const agentsData = await agentsResp.json();
                displayAgents(agentsData.agents || []);

                const tasksResp = await fetch(`${API_BASE}/tasks?limit=5`);
                const tasksData = await tasksResp.json();
                displayTasks(tasksData.tasks || []);
            } catch (e) {
                console.error(e);
            }
        }

        function displayAgents(agents) {
            const container = document.getElementById('agents');
            container.innerHTML = agents.map(a => `
                <div class="agent">
                    <span><span class="status ${a.status}"></span>${a.agent_name || a.agent_id}</span>
                    <span>${a.status}</span>
                </div>
            `).join('');
        }

        function displayTasks(tasks) {
            const container = document.getElementById('tasks');
            if (tasks.length === 0) {
                container.innerHTML = '<p>No active tasks</p>';
                return;
            }
            container.innerHTML = tasks.map(t => `
                <div class="agent">
                    <span>${t.description || t.task_id}</span>
                    <span>${t.status}</span>
                </div>
            `).join('');
        }

        fetchData();
        setInterval(fetchData, 10000);
    </script>
